INSERT INTO stock_basic (
    canonical_symbol, symbol, name, market, list_date, delisted, list_status
) VALUES (
    #{canonicalSymbol}, #{symbol}, #{name}, #{market}, #{listDate}, #{delisted},
    CASE WHEN #{delisted} = TRUE THEN 'DELISTED' ELSE 'UNKNOWN' END
)

mapper.select:
SELECT  FROM stock_basic

ORDER BY canonical_symbol ASC
LIMIT #{limit} OFFSET #{offset}

SELECT  FROM stock_basic
WHERE canonical_symbol IN
#{id}

SELECT s.id, s.canonical_symbol, s.symbol, s.name, s.market, s.name_cn, s.name_hk, s.name_en, s.short_name, s.pinyin_full, s.pinyin_abbr, s.exchange, s.currency, s.security_type, s.list_status, s.data_source, s.source_updated_at, s.source_hash, s.list_date, s.delisted, s.created_at, s.updated_at, CASE WHEN EXISTS ( SELECT 1 FROM stock_alias ae WHERE ae.stock_basic_id = s.id AND ae.normalized_alias = #{query} ) THEN TRUE ELSE FALSE END AS alias_exact, CASE WHEN EXISTS ( SELECT 1 FROM stock_alias ap WHERE ap.stock_basic_id = s.id AND ap.normalized_alias LIKE CONCAT(#{query}, '%') ) THEN TRUE ELSE FALSE END AS alias_prefix, CASE WHEN EXISTS ( SELECT 1 FROM stock_alias ac WHERE ac.stock_basic_id = s.id AND ac.normalized_alias LIKE CONCAT('%', #{query}, '%') ) THEN TRUE ELSE FALSE END AS alias_contains FROM stock_basic s
AND s.delisted = FALSE AND s.list_status != 'DELISTED'
AND s.market IN
#{market}
AND s.security_type IN
#{type}
AND ( UPPER(s.canonical_symbol) = #{queryUpper}
OR s.canonical_symbol = #{canonicalQuery}
OR UPPER(s.symbol) = #{queryUpper}
OR (s.market = 'HK' AND s.symbol = #{hkSymbol})
OR LOWER(COALESCE(s.name, '')) LIKE CONCAT('%', #{query}, '%') OR LOWER(COALESCE(s.name_cn, '')) LIKE CONCAT('%', #{query}, '%') OR LOWER(COALESCE(s.name_hk, '')) LIKE CONCAT('%', #{query}, '%') OR LOWER(COALESCE(s.name_en, '')) LIKE CONCAT('%', #{query}, '%') OR LOWER(COALESCE(s.short_name, '')) LIKE CONCAT('%', #{query}, '%') OR LOWER(COALESCE(s.pinyin_full, '')) LIKE CONCAT(#{query}, '%') OR LOWER(COALESCE(s.pinyin_abbr, '')) LIKE CONCAT(#{query}, '%') OR EXISTS ( SELECT 1 FROM stock_alias ax WHERE ax.stock_basic_id = s.id AND ax.normalized_alias LIKE CONCAT('%', #{query}, '%') ) )
